"""Build a standalone, evidence-linked R1 analysis dashboard (no network/dependencies)."""
from __future__ import annotations
import json
from pathlib import Path
from html import escape

ROOT=Path(__file__).resolve().parents[1]
STUDY=ROOT/'artifacts'/'r1_blinded_synthetic'


def main():
    predictions=json.loads((STUDY/'evaluator_results.json').read_text())['cases']
    scored={row['id']:row for row in json.loads((STUDY/'scored_results.json').read_text())['cases']}
    result=[]
    for row in predictions:
        case=row['case'];place=STUDY/'evaluator_inputs'/case
        contract=json.loads((place/'contract.json').read_text());trace=json.loads((place/'trace.json').read_text())
        cert=json.loads((place/'certificate.json').read_text())
        scored_row=scored[case]
        result.append({'id':case,'contract':contract,'trace':trace,'certificate':cert,
                       'prediction':row,'expected_epistemic_verdict':scored_row['expected_epistemic_verdict'],
                       'synthetic_reference_truth':scored_row['actual_synthetic_truth']})
    payload=json.dumps(result,separators=(',',':'),ensure_ascii=True).replace('<','\\u003c')
    html=HEAD.replace('__DATA__',payload)
    dest=ROOT/'VEAP_R1_Offline_Assurance_Explorer.html'
    dest.write_text(html,encoding='utf-8')
    print(json.dumps({'path':str(dest),'case_count':len(result),'bytes':dest.stat().st_size},indent=2))

HEAD=r'''<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1" />
<title>VEAP R1 · Evidence-Sufficient Embodied Evaluation</title>
<style>
:root{--bg:#0a111c;--layer:#111d2a;--layer2:#172635;--line:#28384b;--muted:#93a6bb;--text:#ecf3f9;--mint:#94f55b;--amber:#ffcc66;--red:#ff6e81;--blue:#65b9fc;font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;color:var(--text);color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 85% 0%,#142934 0%,#0a111c 55%)}header{height:72px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 26px;background:#0b1520cc;gap:12px}.brand{font-size:22px;font-weight:830;letter-spacing:-.8px}.brand span{color:var(--mint)}.brand small{font-size:11px;letter-spacing:1.1px;font-weight:600;color:var(--muted);display:block;margin-top:3px}.headline-meta{font-size:12px;color:var(--muted)}.dot{height:9px;width:9px;background:var(--mint);border-radius:50%;display:inline-block;box-shadow:0 0 12px #94f55b77;margin-right:7px}main{display:grid;grid-template-columns:250px minmax(560px,1fr) 340px;min-height:calc(100vh - 72px)}aside{padding:21px 15px;border-right:1px solid var(--line)}.right{border-left:1px solid var(--line);border-right:0}.section-label{color:#7995aa;font-weight:700;font-size:10px;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:14px}button{cursor:pointer;color:inherit;border:0;background:none;font:inherit}.scenario{width:100%;text-align:left;padding:13px 12px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;gap:8px;border:1px solid transparent;margin-bottom:6px;color:#a8bfd0;font-size:12px}.scenario:hover{background:#182b3b}.scenario.active{background:#192e32;border-color:#4c8155;color:white}.scenario b{font-weight:650}.mini{font-size:10px;font-weight:750;padding:4px 6px;border-radius:5px;letter-spacing:.3px}.COMPLIANT{background:#194b31;color:#8ff4b4}.VIOLATING{background:#532a36;color:#ff9bab}.INCONCLUSIVE{background:#584422;color:#ffe09d}.panel{background:linear-gradient(165deg,#172534,#121f2e);border:1px solid #2b3a4b;border-radius:13px;padding:16px}.panel h2{font-size:12px;margin:0 0 14px;font-weight:750;letter-spacing:.1px;color:#dde9f3}.main-area{padding:21px 22px 22px;min-width:0}.topline{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}.page-title{font-size:22px;margin:4px 0;letter-spacing:-.8px}.sub{font-size:12px;color:var(--muted)}.status{font-size:11px;letter-spacing:.6px;padding:7px 11px;border-radius:8px;font-weight:800}.twocol{display:grid;grid-template-columns:1.5fr 1fr;gap:14px}.grid{display:grid;gap:14px}.metr{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px}.metric{padding:13px;background:var(--layer);border:1px solid var(--line);border-radius:10px}.metric strong{font-size:18px;display:block;margin-bottom:3px}.metric small{font-size:10px;color:var(--muted)}.scene{width:100%;height:auto;aspect-ratio:1.8;background:#0b1520;border:1px solid #304050;border-radius:8px;overflow:hidden}.legend{display:flex;gap:16px;font-size:10px;color:#9db2c4;align-items:center;margin-top:11px;flex-wrap:wrap}.legend i{display:inline-block;width:9px;height:9px;border-radius:3px;margin-right:5px}.seek{display:flex;align-items:center;gap:13px;margin-top:12px}.seek button{border:1px solid #3c5767;background:#1b3640;border-radius:7px;padding:8px 12px;font-size:11px}.seek input{flex:1;accent-color:var(--mint);min-width:30px}.smalltext{font-size:11px;line-height:1.5;color:#abc0d0}.table{width:100%;border-collapse:collapse;font-size:11px}.table td,.table th{padding:9px 6px;border-bottom:1px solid #2a4050;text-align:left}.table th{font-size:9px;letter-spacing:.7px;color:#8ca6ba;text-transform:uppercase}.table tr:last-child td{border-bottom:0}.tag{display:inline-block;padding:3px 6px;border-radius:5px;background:#213744;color:#c8e3ee}.hash{font:10px ui-monospace,SFMono-Regular,Consolas,monospace;color:#b4c9d8;overflow-wrap:anywhere;padding:9px 10px;background:#0b1520;border:1px solid #2e4152;border-radius:7px}.rule{background:#101f2b;border:1px solid #2c4151;padding:11px;border-radius:9px;margin-bottom:8px}.rule-title{font-size:11px;font-weight:720;margin-bottom:9px}.rule p{font-size:10px;color:#b0c5d3;margin:6px 0}.warning{border-left:3px solid #cfa147;background:#40352066;color:#e9d09a;padding:12px;font-size:11px;line-height:1.65;border-radius:6px}.timeline{height:112px;width:100%;border:1px solid #2f4052;border-radius:7px;background:#0b1520}.footer{font-size:10px;color:#86a0b3;margin-top:14px;line-height:1.65}.chip-row{display:flex;gap:8px;flex-wrap:wrap}.chip{font-size:10px;color:#bdd3df;border:1px solid #3a4f60;border-radius:6px;padding:5px 7px}.num{font-feature-settings:"tnum"}.right .panel{margin-bottom:12px}.sidebar-note{padding:11px;font-size:11px;line-height:1.5;border:1px solid #2e4353;border-radius:9px;color:#acc7d7;background:#13222d}.scrollbox{max-height:210px;overflow:auto} .kpis{display:flex;gap:10px;flex-wrap:wrap} .kpi{font-size:10px;white-space:nowrap;padding:6px 8px;border:1px solid #2c4251;border-radius:6px;color:#b1c8d5} .good{color:var(--mint)} .bad{color:var(--red)} .review{color:var(--amber)}@media(max-width:1230px){main{grid-template-columns:215px minmax(500px,1fr)}.right{grid-column:2;border-left:0;padding-top:0}.metr{grid-template-columns:repeat(3,1fr)}}@media(max-width:780px){header{height:auto;padding:16px;flex-wrap:wrap}main{display:block}aside{border-right:0;border-bottom:1px solid var(--line)}.scenario{display:inline-flex;width:auto;max-width:100%;margin-right:5px}.main-area{padding:15px}.right{padding:15px}.twocol{display:block}.twocol>.panel{margin-bottom:14px}.metr{grid-template-columns:repeat(2,1fr)}}
</style></head>
<body><header><div class="brand"><span>VEAP</span> / R1 <small>EVIDENCE-SUFFICIENT EMBODIED EVALUATION</small></div><div class="headline-meta"><span class="dot"></span>OFFLINE RESEARCH EXPLORER &nbsp; · &nbsp; CONSTRUCTED SYNTHETIC DATA &nbsp; · &nbsp; NOT HARDWARE ASSURANCE</div></header>
<main><aside><div class="section-label">Controlled executions · 6</div><div id="scenarioList"></div><div class="section-label" style="margin-top:25px">Research boundary</div><div class="sidebar-note">These are authored demonstration cases, not independent scenes. Evaluator inputs exclude the separately stored high-rate reference traces. No external scientific validation, sensor authenticity, or SOTA result is claimed.</div></aside>
<div class="main-area"><div class="topline"><div><div class="section-label" style="margin-bottom:4px">VEAP certificate / evidence viewer</div><h1 class="page-title" id="caseTitle">—</h1><div class="sub" id="caseSub"></div></div><span class="status" id="caseStatus"></span></div>
<div class="metr"><div class="metric"><small>VEAP VERDICT</small><strong id="metricVerdict"></strong></div><div class="metric"><small>SEPARATE CHECKER</small><strong id="metricChecker"></strong></div><div class="metric"><small>UNRESOLVED WINDOWS</small><strong id="metricGaps"></strong></div></div>
<div class="twocol"><section class="panel"><h2>Spatial execution / exclusion zone</h2><svg id="trajectory" class="scene" viewBox="0 0 640 355" aria-label="Recorded robot positions, goal, and exclusion zone"></svg><div class="legend"><span><i style="background:#94f55b"></i>Observed pose</span><span><i style="background:#ff6e81"></i>Keep-out region</span><span><i style="background:#65b9fc"></i>Goal tolerance</span><span>Lines are visual guides, not certified interpolation</span></div><div class="seek"><button id="playPause" aria-label="Play recorded observations">▶ Play</button><input id="seek" type="range" min="0" max="100" value="0" aria-label="Seek observation timestamp"><span class="num" id="clock" style="font-size:11px">0.00s</span></div></section>
<section class="panel"><h2>Requirement decision</h2><div id="rules"></div><div class="section-label" style="margin-top:18px;margin-bottom:8px">Explanation coverage</div><div id="gapDetail" class="smalltext"></div></section></div>
<div class="grid" style="grid-template-columns:1fr;gap:14px;margin-top:14px"><section class="panel"><h2>Time-indexed evidence and unresolved coverage</h2><svg id="timeline" viewBox="0 0 850 112" class="timeline" aria-label="Timeline with pose observations and evidence sufficiency gaps"></svg><div class="kpis" style="margin-top:12px"><span class="kpi" id="sampleCount"></span><span class="kpi" id="provenance"></span><span class="kpi">Independent truth never fed to evaluator</span></div></section>
<section class="panel"><h2>Comparator analysis</h2><table class="table"><thead><tr><th>Evaluator</th><th>Result</th><th>Scientific interpretation</th></tr></thead><tbody id="baselineRows"></tbody></table></section></div>
<div class="footer">VEAP R1 tests conditional evidence-sufficiency. The motion and pose-error bounds shown are assumed and must be calibrated for hardware. A cryptographic digest does not prove that recorded positions were true. A conclusive verdict applies only to the stated contract and input evidence.</div></div>
<aside class="right"><div class="section-label">Evidence / independent check</div><section class="panel"><h2>Proof summary</h2><div class="chip-row"><span class="chip" id="sourceKind"></span><span class="chip">UNATTESTED</span><span class="chip">Separate checker</span></div><p class="smalltext" id="assumptions"></p></section><section class="panel"><h2>Record identity</h2><div class="section-label" style="margin:7px 0">Contract SHA-256</div><div class="hash" id="contractHash"></div><div class="section-label" style="margin:12px 0 7px">Trace SHA-256</div><div class="hash" id="traceHash"></div><div class="section-label" style="margin:12px 0 7px">Certificate SHA-256</div><div class="hash" id="certHash"></div></section><section class="panel"><h2>Evidence records</h2><div id="evidenceRecords" class="scrollbox"></div></section><div class="warning">This viewer is for inspecting already-computed certificates. It does not execute the reference checker in the browser. The source package provides the separate Python verification process.</div></aside></main>
<script>const CASES=__DATA__;let selected=0;let clock=0;let playing=null;const $=id=>document.getElementById(id);
function label(x){return String(x).replaceAll('_',' ').replace(/\b\w/g,ch=>ch.toUpperCase())}
function safeText(t){return String(t??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}
function statusMarkup(v){return `<span class="mini ${v}">${v}</span>`}
function paintMenu(){ $('scenarioList').innerHTML=CASES.map((r,i)=>`<button class="scenario ${i===selected?'active':''}" data-id="${i}"><b>${safeText(label(r.id))}</b>${statusMarkup(r.prediction.veap)}</button>`).join(''); document.querySelectorAll('.scenario').forEach(b=>b.onclick=()=>choose(+b.dataset.id));}
function choose(index){selected=index;clock=0;clearInterval(playing);playing=null;$('playPause').textContent='▶ Play';paintMenu();refresh()}
function pointToXY(p,minx,maxx,miny,maxy){let k=Math.min(520/(maxx-minx),260/(maxy-miny));return [320+(p[0]-(minx+maxx)/2)*k,177-(p[1]-(miny+maxy)/2)*k]}
function refresh(){const item=CASES[selected],c=item.contract,t=item.trace.samples,cert=item.certificate;const verdict=item.prediction.veap;
$('caseTitle').textContent=label(item.id);$('caseSub').textContent='Robot-centre observations · map frame · mission 0–2 s';$('caseStatus').textContent=verdict;$('caseStatus').className=`status ${verdict}`;$('metricVerdict').textContent=verdict;$('metricChecker').textContent=item.prediction.checker;$('metricGaps').textContent=String(cert.unresolved_coverage.length);$('sourceKind').textContent='SOURCE: '+item.trace.source_kind;$('assumptions').textContent=`Max speed ${c.max_speed_mps} m/s · pose error ≤ ${c.position_uncertainty_m} m · circular footprint radius ${c.robot_radius_m} m · declared frame ${c.frame_id}`;
$('contractHash').textContent=cert.contract_sha256;$('traceHash').textContent=cert.trace_canonical_sha256;$('certHash').textContent=cert.certificate_sha256;
$('rules').innerHTML=Object.entries(cert.requirements).map(([key,v])=>`<div class="rule"><div class="rule-title">${safeText(label(key))} &nbsp; ${statusMarkup(v.verdict)}</div><p>${v.witnesses.length} witness(es) · ${v.unresolved_intervals.length} unresolved time window(s)</p></div>`).join('');
$('gapDetail').innerHTML=cert.unresolved_coverage.length?cert.unresolved_coverage.map(g=>`<div class="rule"><span class="review">${safeText(label(g.type))}</span><p>${safeText(g.interval_s?.map(x=>x.toFixed(4)).join(' – '))} s</p><p>${safeText(g.request||'')}</p></div>`).join(''):'<span class="good">No unresolved obligations for the stated requirements.</span>';
$('baselineRows').innerHTML=Object.entries(item.prediction.baselines).map(([k,v])=>`<tr><td>${safeText(label(k))}</td><td>${statusMarkup(v)}</td><td>${v===verdict?'Same verdict as VEAP':'Different verdict; examine evidence assumptions'}</td></tr>`).join('')+`<tr><td><b>VEAP certificate</b></td><td>${statusMarkup(verdict)}</td><td>Checked against separate rule implementation</td></tr>`;
$('sampleCount').textContent=`Observed samples: ${t.length}`;$('provenance').textContent=`Observed source: ${item.trace.source_kind}`;
$('evidenceRecords').innerHTML=t.map((p,i)=>`<div class="rule" style="padding:7px 9px;margin-bottom:5px"><div class="rule-title">${safeText(p.event_id||'record-'+i)} &nbsp; <span class="num" style="color:var(--muted)">${Number(p.t_s).toFixed(2)} s</span></div><div class="smalltext">${p.x===undefined?'Pose missing':`(${Number(p.x).toFixed(2)}, ${Number(p.y).toFixed(2)}) m`} · ${safeText(p.frame_id)} · ${p.sensor_healthy?'sensor marked healthy':'sensor unhealthy'}</div></div>`).join('');
const pose=t.filter(p=>typeof p.x==='number'&&typeof p.y==='number');let vals=[...pose.map(p=>[p.x,p.y]),[c.keepout[0],c.keepout[1]],[c.keepout[2],c.keepout[3]],[c.goal.x,c.goal.y]];let minx=Math.min(...vals.map(v=>v[0]))-0.6,maxx=Math.max(...vals.map(v=>v[0]))+0.6,miny=Math.min(...vals.map(v=>v[1]))-.8,maxy=Math.max(...vals.map(v=>v[1]))+.8;if(maxy-miny<2.8){let ymid=(miny+maxy)/2;miny=ymid-1.4;maxy=ymid+1.4};if(maxx-minx<2.8){let xmid=(minx+maxx)/2;minx=xmid-1.4;maxx=xmid+1.4}
const xy=(x,y)=>pointToXY([x,y],minx,maxx,miny,maxy);let out='';for(let i=0;i<11;i++){let x=i*64;out+=`<line x1="${x}" x2="${x}" y1="0" y2="355" stroke="#243b48" opacity=".65"/>`;};for(let i=0;i<7;i++){let y=i*59;out+=`<line x1="0" x2="640" y1="${y}" y2="${y}" stroke="#243b48" opacity=".65"/>`}
let [z1x,z1y]=xy(c.keepout[0],c.keepout[3]);let [z2x,z2y]=xy(c.keepout[2],c.keepout[1]);out+=`<rect x="${z1x}" y="${z1y}" width="${z2x-z1x}" height="${z2y-z1y}" fill="#e45672" fill-opacity=".24" stroke="#ff6e81" stroke-width="2" stroke-dasharray="5 5"/>`;let [gx,gy]=xy(c.goal.x,c.goal.y);let k=Math.min(520/(maxx-minx),260/(maxy-miny));out+=`<circle cx="${gx}" cy="${gy}" r="${Math.max(3,c.goal.tolerance_m*k)}" fill="#65b9fc" fill-opacity=".14" stroke="#65b9fc" stroke-dasharray="4 4"/>`;
for(let i=1;i<pose.length;i++){let [x1,y1]=xy(pose[i-1].x,pose[i-1].y),[x2,y2]=xy(pose[i].x,pose[i].y);out+=`<path d="M${x1},${y1} L${x2},${y2}" fill="none" stroke="#8aea65" stroke-width="2.6" opacity=".72"/>`}
for(let p of pose){let [x,y]=xy(p.x,p.y);out+=`<circle cx="${x}" cy="${y}" r="5.3" fill="#afff78" stroke="#0b1520" stroke-width="2"/>`};const current=pose.reduce((last,p)=>p.t_s<=clock?p:last,pose[0]);if(current){let [x,y]=xy(current.x,current.y);out+=`<circle cx="${x}" cy="${y}" r="13" fill="none" stroke="#fff" stroke-width="2"/><circle cx="${x}" cy="${y}" r="4" fill="#fff"/>`}$('trajectory').innerHTML=out;
const begin=c.mission_start_s,end=c.mission_end_s;const scale=v=>60+(v-begin)/(end-begin)*730;let tm=`<line x1="60" y1="58" x2="790" y2="58" stroke="#456071" stroke-width="4" stroke-linecap="round"/>`;for(let i=0;i<=4;i++){let sec=begin+(end-begin)*i/4;tm+=`<text x="${scale(sec)}" y="96" fill="#8ea9bb" text-anchor="middle" font-size="12">${sec.toFixed(1)} s</text>`};for(let p of pose){let x=scale(p.t_s);tm+=`<circle cx="${x}" cy="58" r="6" fill="#94f55b" stroke="#0b1520" stroke-width="2"/>`};for(let u of cert.requirements.keepout_continuous.unresolved_intervals){let [l,r]=u.interval_s;tm+=`<rect x="${scale(l)}" y="41" width="${Math.max(2,scale(r)-scale(l))}" height="34" rx="4" fill="#ffb44e" fill-opacity=".4" stroke="#eeb350"/><text x="${(scale(l)+scale(r))/2}" y="31" font-size="10" fill="#ffd388" text-anchor="middle">Evidence gap</text>`};tm+=`<line x1="${scale(clock)}" y1="10" x2="${scale(clock)}" y2="77" stroke="#f4f8fa" stroke-width="2"/>`;$('timeline').innerHTML=tm;
$('clock').textContent=clock.toFixed(2)+'s';$('seek').value=String(Math.round(clock/end*100));}
$('seek').oninput=()=>{clock=CASES[selected].contract.mission_end_s*(+$('seek').value)/100;refresh()};$('playPause').onclick=()=>{if(playing){clearInterval(playing);playing=null;$('playPause').textContent='▶ Play';return}playing=setInterval(()=>{clock+=.05;if(clock>CASES[selected].contract.mission_end_s){clearInterval(playing);playing=null;clock=0;$('playPause').textContent='▶ Play'}refresh()},100);$('playPause').textContent='Ⅱ Pause'};paintMenu();refresh();
</script></body></html>'''

if __name__=='__main__':main()
